import{_ as n,c as s,o as i,ah as a}from"./chunks/framework.BjIn8lrq.js";const u=JSON.parse('{"title":"30. Entwicklungsumgebung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/30-entwicklungsumgebung.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/30-entwicklungsumgebung.md"}'),t={name:"manual/teil-c-entwicklungs-systemdokumentation/30-entwicklungsumgebung.md"};function d(r,e,l,o,c,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="_30-entwicklungsumgebung" tabindex="-1">30. Entwicklungsumgebung <a class="header-anchor" href="#_30-entwicklungsumgebung" aria-label="Permalink to &quot;30. Entwicklungsumgebung&quot;">​</a></h1><p>Dieses Kapitel beschreibt, wie Sie Qonnectra auf dem eigenen Rechner zum Laufen bringen, um daran zu entwickeln. Es gibt zwei Wege:</p><ul><li><strong>Backend und Frontend direkt auf dem Rechner</strong>, nur die Datenbank im Container. Änderungen am Code wirken sofort: Django lädt sich bei jeder Änderung neu, Vite tauscht geänderte Komponenten im Browser aus. Das ist der Weg für die tägliche Arbeit am Code, beschrieben in den Abschnitten <a href="#_30-2-backend-starten">Backend starten</a> und <a href="#_30-3-frontend-starten">Frontend starten</a>.</li><li><strong>Alles in Containern</strong>, so wie auf einem Server. Jede Änderung am Code braucht einen neuen Build der Images. Das ist der Weg, um das Zusammenspiel aller Dienste zu prüfen – Caddy, nginx, QGIS Server, WebDAV –, beschrieben in den Abschnitten <a href="#_30-4-varianten-der-docker-compose-dateien">Varianten der Docker-Compose-Dateien</a> und <a href="#_30-5-lokales-https-und-zertifikate">Lokales HTTPS und Zertifikate</a>.</li></ul><p>Alle Pfade in diesem Kapitel sind relativ zum Wurzelverzeichnis des Repositorys.</p><h2 id="_30-1-voraussetzungen" tabindex="-1">30.1 Voraussetzungen <a class="header-anchor" href="#_30-1-voraussetzungen" aria-label="Permalink to &quot;30.1 Voraussetzungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Werkzeug</th><th>Version</th><th>Wofür</th></tr></thead><tbody><tr><td>Python</td><td>3.12 oder neuer</td><td>Backend; <code>backend/.python-version</code> nennt 3.12</td></tr><tr><td><a href="https://docs.astral.sh/uv/" target="_blank" rel="noreferrer">uv</a></td><td>aktuell</td><td>Abhängigkeiten des Backends, gesperrt in <code>backend/uv.lock</code></td></tr><tr><td>GDAL und GEOS</td><td>aus dem Paketmanager</td><td>GeoDjango; nur für das Backend auf dem Rechner</td></tr><tr><td>Node.js</td><td>22</td><td>Frontend; die Images bauen mit <code>node:22-alpine</code></td></tr><tr><td>Docker Engine, Docker Compose</td><td>20.10 bzw. 2.24.4 oder neuer, mit BuildKit</td><td>Datenbank, und alle Dienste im zweiten Weg</td></tr></tbody></table><p>Unter Linux findet Django GDAL und GEOS ohne weitere Einstellung, sobald die Bibliotheken über den Paketmanager installiert sind. Für macOS und Windows stehen die Pfade fest in <code>backend/core/settings.py</code>: unter macOS die von Homebrew (<code>/opt/homebrew/opt/gdal</code>, <code>/opt/homebrew/opt/geos</code>), unter Windows die von OSGeo4W (<code>C:\\OSGeo4W\\bin</code>). Liegen die Bibliotheken woanders, passen Sie die Pfade dort an.</p><p>Für den Betrieb aller Dienste in Containern rechnet <code>deployment/README.md</code> mit 8 CPU-Kernen und 16 GB Arbeitsspeicher; QGIS Server und die Datenbank sind die größten Posten. Die Ports 80 und 443 müssen frei sein.</p><h2 id="_30-2-backend-starten" tabindex="-1">30.2 Backend starten <a class="header-anchor" href="#_30-2-backend-starten" aria-label="Permalink to &quot;30.2 Backend starten&quot;">​</a></h2><p>Das Backend liest seine Einstellungen aus <code>deployment/.env</code>, auch wenn es nicht im Container läuft (<code>load_dotenv</code> in <code>backend/core/settings.py</code>). Variablen, die in der Shell bereits gesetzt sind, haben Vorrang vor der Datei. So bleibt eine einzige <code>.env</code> für beide Wege, und was auf dem Rechner anders sein muss, setzen Sie beim Start.</p><ol><li><p>Legen Sie <code>deployment/.env</code> aus der Vorlage an und setzen Sie mindestens <code>DJANGO_SECRET_KEY</code>, <code>DB_NAME</code>, <code>DB_USER</code> und <code>DB_PASSWORD</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/.env.production.template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/.env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Was die übrigen Variablen bedeuten, beschreibt Abschnitt <a href="./35-bereitstellung-und-infrastruktur.html#_35-7-referenz-der-umgebungsvariablen">Referenz der Umgebungsvariablen</a>.</p></li><li><p>Starten Sie eine Datenbank. Für die Entwicklung genügt das Basis-Image von PostGIS, auf dem das Image von Qonnectra aufbaut; die zusätzliche Erweiterung pgRouting nutzt der Code nicht.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qonnectra-dev-db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:5440:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_DB=qonnectra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_USER=qonnectra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POSTGRES_PASSWORD=qonnectra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  postgis/postgis:17-3.5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>127.0.0.1</code> vor dem Port hält die Datenbank vom Netz fern; ohne ihn ist sie auf allen Schnittstellen des Rechners erreichbar. Die Werte müssen zu <code>DB_NAME</code>, <code>DB_USER</code> und <code>DB_PASSWORD</code> in der <code>.env</code> passen. Die Erweiterungen, die das Backend braucht – PostGIS, <code>pgcrypto</code>, <code>pg_trgm</code> –, legen die Migrationen selbst an.</p></li><li><p>Installieren Sie die Abhängigkeiten:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Setzen Sie für die Sitzung, was vom Container abweicht:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DB_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost DB_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5440</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEBUG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">True USE_COOKIE_DOMAIN_MIDDLEWARE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">False \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CORS_ALLOWED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:5173</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Legen Sie Tabellen, Stammdaten und ein Konto für die Anmeldung an:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load_initial_data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> createsuperuser</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><p>Starten Sie den Entwicklungsserver:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runserver</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><p>Die Schnittstelle antwortet dann unter <code>http://localhost:8000/api/v1/</code>, der Administrationsbereich unter <code>http://localhost:8000/admin/</code>. Ohne Caddy davor gibt es die Trennung der beiden Adressen nicht.</p><p><code>DEBUG=True</code> ist auf dem Rechner keine Bequemlichkeit, sondern Voraussetzung für mehrere Funktionen:</p><ul><li><strong>Anhänge</strong> liefert das Backend nur mit <code>DEBUG</code> selbst aus. Sonst antwortet es mit einem <code>X-Accel-Redirect</code>, den nur nginx auflösen kann, und der Download bleibt leer.</li><li>Die <strong>Swagger-Oberfläche</strong> unter <code>/api/v1/docs/</code> und das Schema unter <code>/api/v1/schema/</code> gibt es nur mit <code>DEBUG</code>, ebenso die im Browser bedienbare Schnittstelle von Django REST Framework, siehe Abschnitt <a href="./32-rest-api.html#_32-7-openapi-schema-und-typgenerierung">OpenAPI-Schema und Typgenerierung</a>.</li><li>Die <strong>Stylesheets des Administrationsbereichs</strong> liefert <code>runserver</code> nur mit <code>DEBUG</code> aus.</li></ul><p><code>CORS_ALLOWED_ORIGINS</code> muss die Adresse des Frontends nennen, weil der Browser Kacheln, Suchtreffer und Speichervorgänge direkt beim Backend auf einem anderen Port anfragt; die Vorlage trägt dort die Adressen eines Servers ein, und der Browser verweigert die Antworten.</p><p><code>USE_COOKIE_DOMAIN_MIDDLEWARE=False</code> sorgt dafür, dass die Anmelde-Cookies ohne Domain gesetzt werden. Mit der Domain aus der Vorlage verwirft der Browser sie auf <code>localhost</code>, und die Anmeldung scheitert, ohne dass eine Meldung erscheint.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>In VS Code liegen dieselben Schritte als Aufgaben in <code>.vscode/tasks.json</code> („Django Migrate“, „Django Runserver“ usw.), Startkonfigurationen zum Debuggen in <code>.vscode/launch.json</code>. Die Aufgaben setzen die Variablen aus Schritt 4 nicht; tragen Sie sie in das <code>env</code> der Aufgaben bzw. Startkonfigurationen ein oder starten Sie VS Code aus einer Shell, in der sie gesetzt sind. In <code>deployment/.env</code> gehören sie nicht: Die Datei gilt auch für die Container, und dort liefe das Backend mit <code>DEBUG</code>. Die Aufgabe „Django Migrate“ ruft <code>python</code> statt <code>uv run</code> auf und braucht deshalb die aktivierte Umgebung aus <code>backend/.venv</code>.</p></div><h2 id="_30-3-frontend-starten" tabindex="-1">30.3 Frontend starten <a class="header-anchor" href="#_30-3-frontend-starten" aria-label="Permalink to &quot;30.3 Frontend starten&quot;">​</a></h2><ol><li><p>Installieren Sie die Abhängigkeiten nach <code>frontend/package-lock.json</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Legen Sie die Einstellungen an:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Die Vorlage zeigt mit <code>API_URL</code> und <code>PUBLIC_API_URL</code> auf das Backend unter <code>http://localhost:8000/api/v1/</code>. <code>API_URL</code> nutzt das Frontend für Anfragen vom Server aus, <code>PUBLIC_API_URL</code> der Browser; auf dem Rechner sind beide gleich. Für die Hintergrundkarte ergänzen Sie <code>PUBLIC_TILE_SERVER_URL</code>, wenn ein Kachelserver erreichbar ist; die Vorlage enthält die Variable nicht, und ohne sie fällt die Karte auf die Rasterkacheln von OpenStreetMap zurück.</p></li><li><p>Starten Sie den Entwicklungsserver:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><p>Die Weboberfläche läuft dann unter <code>http://localhost:5173</code>. Melden Sie sich mit dem Konto aus Schritt 5 des vorigen Abschnitts an; ausgewählt ist danach das Projekt „Default“, das <code>load_initial_data</code> anlegt.</p><p>Die Anmeldung läuft über die Formularaktion des Frontends: Sie übernimmt die Cookies aus der Antwort des Backends und setzt sie selbst für <code>localhost</code>. Weil Cookies nicht an den Port gebunden sind, schickt der Browser sie auch an <code>localhost:8000</code>. Sie tragen das Attribut <code>Secure</code>, das Chromium und Firefox auf <code>localhost</code> auch ohne HTTPS akzeptieren.</p><h2 id="_30-4-varianten-der-docker-compose-dateien" tabindex="-1">30.4 Varianten der Docker-Compose-Dateien <a class="header-anchor" href="#_30-4-varianten-der-docker-compose-dateien" aria-label="Permalink to &quot;30.4 Varianten der Docker-Compose-Dateien&quot;">​</a></h2><p><code>deployment/</code> enthält drei Compose-Dateien:</p><table tabindex="0"><thead><tr><th>Datei</th><th>Gedacht für</th><th>Zustand</th></tr></thead><tbody><tr><td><code>docker-compose.yml</code></td><td>den Betrieb auf einem Server</td><td>vollständig, alle zehn Dienste; braucht öffentliche Domains, weil Caddy Zertifikate bei Let’s Encrypt holt</td></tr><tr><td><code>docker-compose.dev.yml</code></td><td>alle Dienste lokal unter <code>*.localhost</code></td><td>startet nicht, siehe unten</td></tr><tr><td><code>docker-compose.override.yml.template</code></td><td>eigene Anpassungen</td><td>nur auskommentierte Beispiele: Containernamen, Datenbankport, Code einbinden, Worker skalieren</td></tr></tbody></table><p><code>docker-compose.dev.yml</code> verzichtet auf <code>backend-wms</code> und <code>wireguard</code>, legt die Datenbank in den Ordner <code>deployment/postgres/data</code> statt in ein Volume und öffnet ihren Port als 5440. Die Datei startet zum Stand des Handbuchs aber nicht: Sie bindet <code>nginx/nginx.conf</code> – eine vollständige Hauptkonfiguration mit <code>worker_processes</code> und <code>http</code>-Block – als <code>conf.d/default.conf</code> ein, und nginx bricht mit „&quot;worker_processes&quot; directive is not allowed here“ ab. Dazu kommt, dass sie die Adressen direkt unter <code>localhost</code> setzt (<code>api.localhost</code>, <code>app.localhost</code>), wo kein Browser Cookies mit <code>Domain=.localhost</code> annimmt – <code>localhost</code> gilt als öffentliches Suffix.</p><p>Wenn Sie alle Dienste lokal betreiben wollen, nehmen Sie deshalb die Datei für den Server und passen sie über eine Override-Datei an. Docker Compose liest <code>docker-compose.override.yml</code> neben <code>docker-compose.yml</code> automatisch mit ein.</p><ol><li><p>Wählen Sie eine Basisdomain eine Ebene unter <code>localhost</code>, etwa <code>qonnectra.localhost</code>. Alle Namen unter <code>localhost</code> zeigen ohne Eintrag in <code>/etc/hosts</code> auf den eigenen Rechner. Tragen Sie in <code>deployment/.env</code> ein:</p><ul><li>die sechs Adressen, <code>APP_DOMAIN=app.qonnectra.localhost</code>, <code>API_DOMAIN=api.qonnectra.localhost</code> usw.,</li><li><code>COOKIE_DOMAIN=.qonnectra.localhost</code> und <code>USE_COOKIE_DOMAIN_MIDDLEWARE=True</code>,</li><li><code>CORS_ALLOWED_ORIGINS=https://app.qonnectra.localhost</code> und <code>CSRF_TRUSTED_ORIGINS=https://api.qonnectra.localhost,https://app.qonnectra.localhost,https://admin.qonnectra.localhost</code>,</li><li>in <code>DJANGO_ALLOWED_HOSTS</code> die Adressen <code>api.</code>, <code>admin.</code>, <code>files.</code> und <code>qgis.</code> sowie <code>backend</code> – unter diesem Namen spricht das Frontend das Backend im Docker-Netz an, und Caddy prüft jede Anfrage an <code>files.</code> und <code>qgis.</code> beim Backend unter deren eigenem Namen,</li><li><code>API_URL=http://backend:8000/api/v1/</code>, <code>PUBLIC_API_URL=https://api.qonnectra.localhost/api/v1/</code> und <code>PUBLIC_TILE_SERVER_URL=https://tiles.qonnectra.localhost</code>.</li></ul></li><li><p>Kopieren Sie <code>Caddyfile.production</code> nach <code>Caddyfile.local</code> und ergänzen Sie in jedem der sechs Adressblöcke die Zeile <code>tls internal</code>. Caddy stellt die Zertifikate dann selbst aus, statt sie bei Let’s Encrypt anzufragen, siehe nächster Abschnitt.</p></li><li><p>Legen Sie <code>deployment/docker-compose.override.yml</code> an:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  caddy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./Caddyfile.local:/etc/caddy/Caddyfile:ro</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Docker Compose führt die Volumes beider Dateien nach ihrem Ziel im Container zusammen. Der Eintrag ersetzt nur die Einbindung von <code>Caddyfile.production</code>, alle übrigen Volumes von <code>caddy</code> bleiben, wie sie sind.</p></li><li><p>Bauen und starten Sie alles:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li></ol><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Image der Datenbank lässt sich zum Stand des Handbuchs aus einem leeren Cache nicht mehr bauen. <code>deployment/postgres/Dockerfile</code> installiert pgRouting über <code>apt.postgresql.org</code> auf <code>postgis/postgis:17-3.5</code>, das auf Debian 11 („bullseye“) beruht, und für bullseye bietet das Repository keine Pakete mehr an. Sie liegen unverändert unter <code>apt-archive.postgresql.org</code>. Bis das Dockerfile angepasst ist, bauen Sie das Image über die Override-Datei mit dem Archiv:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  db</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      dockerfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      dockerfile_inline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        FROM postgis/postgis:17-3.5</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        RUN sed -i &#39;s#http://apt.postgresql.org/#http://apt-archive.postgresql.org/#&#39; /etc/apt/sources.list.d/pgdg.list &amp;&amp; \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            apt-get update &amp;&amp; \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            apt-get install -y --no-install-recommends postgresql-17-pgrouting &amp;&amp; \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            rm -rf /var/lib/apt/lists/*</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sind <code>QGIS_DB_USER</code> und <code>QGIS_DB_PASSWORD</code> gesetzt, bricht der allererste Start der Datenbank mit einem leeren Volume ab: <code>deployment/postgres/init.sh</code> greift auf Tabellen zu, die erst die Migrationen des Backends anlegen. Starten Sie die Dienste erneut; ein Volume, das bereits initialisiert ist, durchläuft das Skript nicht noch einmal. Was danach für den QGIS-Benutzer zu tun ist, beschreibt Abschnitt <a href="./35-bereitstellung-und-infrastruktur.html#_35-4-datenbank-postgis-und-datenbankzugang">Datenbank, PostGIS und Datenbankzugang</a>.</p></div><h2 id="_30-5-lokales-https-und-zertifikate" tabindex="-1">30.5 Lokales HTTPS und Zertifikate <a class="header-anchor" href="#_30-5-lokales-https-und-zertifikate" aria-label="Permalink to &quot;30.5 Lokales HTTPS und Zertifikate&quot;">​</a></h2><p>Mit <code>tls internal</code> stellt Caddy die Zertifikate über eine eigene Zertifizierungsstelle aus, die es beim ersten Start anlegt. Der Browser kennt sie nicht und warnt bei jeder der sechs Adressen. Machen Sie ihr Wurzelzertifikat dem Rechner bekannt; es liegt im Volume <code>caddy_data</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> caddy:/data/caddy/pki/authorities/local/root.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./caddy-root.crt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Importieren Sie <code>caddy-root.crt</code> in den Zertifikatsspeicher des Betriebssystems, unter Debian und Ubuntu etwa nach <code>/usr/local/share/ca-certificates/</code> mit anschließendem <code>update-ca-certificates</code>. Firefox und Chromium unter Linux führen einen eigenen Speicher und brauchen den Import zusätzlich in ihren Einstellungen.</p><p><code>deployment/README.md</code> nennt dafür den Befehl <code>docker compose -f docker-compose.dev.yml exec caddy caddy trust</code>. Er installiert das Zertifikat im Container, nicht auf dem Rechner, und hilft dem Browser deshalb nicht.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Zertifizierungsstelle lebt im Volume <code>caddy_data</code>. Wird es gelöscht, etwa mit <code>docker compose down -v</code>, legt Caddy beim nächsten Start eine neue an, und der Import ist zu wiederholen. Um das zu vermeiden, erzeugen Sie eine eigene Zertifizierungsstelle, binden ihr Zertifikat und ihren Schlüssel in den Container ein und nennen sie Caddy im globalen Block von <code>Caddyfile.local</code>:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    pki {</span></span>
<span class="line"><span>        ca local {</span></span>
<span class="line"><span>            root {</span></span>
<span class="line"><span>                cert /etc/caddy/ca/root.crt</span></span>
<span class="line"><span>                key /etc/caddy/ca/root.key</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div></div><h2 id="_30-6-stamm-und-ausgangsdaten-laden" tabindex="-1">30.6 Stamm- und Ausgangsdaten laden <a class="header-anchor" href="#_30-6-stamm-und-ausgangsdaten-laden" aria-label="Permalink to &quot;30.6 Stamm- und Ausgangsdaten laden&quot;">​</a></h2><p>Qonnectra bringt keine Beispieldaten mit, wohl aber die Stammdaten, ohne die keine Ansicht funktioniert. Es gibt zwei Quellen:</p><ul><li><strong>Migrationen</strong> legen die drei Gruppen „Admin“, „Editor“ und „Viewer“ mit ihren Modell- und Routenrechten an (Migrationen <code>0058</code>, <code>0068</code>, <code>0071</code>). Sie sind nach <code>migrate</code> immer da. Was die Gruppen dürfen, beschreibt Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</li><li><strong><code>load_initial_data</code></strong> lädt die Fixtures aus <code>backend/apps/api/fixtures/</code>: <ul><li>das Projekt „Default“ und das Kennzeichen „Default“, beide mit der Nummer 1, samt Netzschema- und Rohrverzweigungs-Einstellungen für dieses Projekt,</li><li>Status, Phasen, Netzebenen, Oberflächen, Bauarten und Firmen,</li><li>Rohr- und Kabeltypen mit ihren Farbzuordnungen, Mikrorohr- und Faserfarben, Mikrorohr- und Faserstatus,</li><li>Netzknoten- und Komponententypen mit ihren Portbelegungen, Gebietstypen,</li><li>Ausbaustatus der Adressen, Typen und Status der Wohneinheiten,</li><li>die Speicherpräferenzen und Dateitypkategorien der Anhänge,</li><li>die Nachschlagelisten der Leitungsauskunft.</li></ul></li></ul><p>Der Container <code>backend</code> ruft <code>migrate</code> und <code>load_initial_data</code> bei jedem Start selbst auf. Auf dem Rechner tun Sie es von Hand, siehe Abschnitt <a href="#_30-2-backend-starten">Backend starten</a>.</p><p><code>load_initial_data</code> lädt die Fixtures in sieben Gruppen. Jede Gruppe hat ein Leitmodell, und sie wird übersprungen, sobald dessen Tabelle eine Zeile enthält – so überlebt der Befehl jeden Neustart, ohne doppelte Einträge anzulegen. Daraus folgt zweierlei:</p><ul><li>Kommt in einer neuen Version eine Fixture zu einer bestehenden Gruppe hinzu, lädt der Befehl sie auf einer Installation, deren Gruppe schon befüllt ist, nie. Laden Sie sie dann einzeln mit <code>uv run manage.py loaddata &lt;name&gt;</code>, solange ihre Tabelle noch leer ist, siehe den Kasten unten.</li><li><code>--force</code> lädt alle Gruppen ohne Prüfung. Die Farbzuordnungen haben eindeutige Schlüssel; auf einer befüllten Datenbank bricht der Befehl an ihnen ab.</li></ul><p>Zwei Fixtures gehören zu keiner Gruppe und werden nie automatisch geladen: <code>container_types.json</code> und <code>valuation_cost_rates.json</code>. Container-Typen und Kostensätze der Wertermittlung legen Sie im Administrationsbereich an, siehe die Abschnitte <a href="./../teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.html#_21-7-container-typen">Container-Typen</a> und <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html#_22-3-kostensatze-der-wertermittlung">Kostensätze der Wertermittlung</a>, oder laden sie mit <code>loaddata</code>.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p><code>loaddata</code> überschreibt Zeilen mit derselben Nummer ohne Rückfrage. Die Fixtures tragen feste Nummern; auf einer Installation, in der jemand schon Container-Typen, Kostensätze oder andere Stammdaten angelegt hat, ersetzt der Befehl diese Einträge. Laden Sie eine Fixture einzeln nur in eine leere Tabelle.</p></div><p>Für Netzdaten, mit denen sich die Ansichten ausprobieren lassen, gibt es keinen mitgelieferten Weg. Sie entstehen über QGIS, über den Excel-Import der Rohre oder über die Schnittstelle, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/24-daten-import-und-export.html">Daten importieren und exportieren</a>.</p>`,44)])])}const k=n(t,[["render",d]]);export{u as __pageData,k as default};
